"use strict";(self.webpackChunkdocumentation=self.webpackChunkdocumentation||[]).push([[657],{732:(e,n,t)=>{t.r(n),t.d(n,{assets:()=>l,contentTitle:()=>s,default:()=>u,frontMatter:()=>o,metadata:()=>a,toc:()=>c});const a=JSON.parse('{"id":"oem-odm/oem-opportunity","title":"DASSET for OEMs","description":"A \\"Blue Ocean\\" Opportunity in Smart Storage","source":"@site/docs/oem-odm/oem-opportunity.md","sourceDirName":"oem-odm","slug":"/oem-odm/oem-opportunity","permalink":"/docs/oem-odm/oem-opportunity","draft":false,"unlisted":false,"editUrl":"https://github.com/PlanetX-Labs/planetx-labs.github.io/tree/main/docs/oem-odm/oem-opportunity.md","tags":[],"version":"current","sidebarPosition":1,"frontMatter":{"sidebar_position":1},"sidebar":"DocsSidebar","previous":{"title":"Set-up your DASSET Data Hub","permalink":"/docs/how-to/getting-started/device-set-up"},"next":{"title":"DASSET Software Platform","permalink":"/docs/oem-odm/oem-software-platform"}}');var r=t(2467),i=t(8453);const o={sidebar_position:1},s="DASSET for OEMs",l={},c=[{value:"A &quot;Blue Ocean&quot; Opportunity in Smart Storage",id:"a-blue-ocean-opportunity-in-smart-storage",level:2},{value:"Flexible Licensing and Branding Options",id:"flexible-licensing-and-branding-options",level:2},{value:"Co-Marketing and Revenue Sharing Opportunities",id:"co-marketing-and-revenue-sharing-opportunities",level:2},{value:"Technical Integration, Certification, and Support",id:"technical-integration-certification-and-support",level:2},{value:"Partner with Us",id:"partner-with-us",level:2}];function d(e){const n={a:"a",h1:"h1",h2:"h2",header:"header",li:"li",p:"p",strong:"strong",ul:"ul",...(0,i.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(n.header,{children:(0,r.jsx)(n.h1,{id:"dasset-for-oems",children:"DASSET for OEMs"})}),"\n",(0,r.jsx)(n.h2,{id:"a-blue-ocean-opportunity-in-smart-storage",children:'A "Blue Ocean" Opportunity in Smart Storage'}),"\n",(0,r.jsxs)(n.p,{children:["As an Original Equipment Manufacturer (OEM) in the storage or smart home industry, partnering with PlanetX Labs\u2019 ",(0,r.jsx)(n.strong,{children:"DASSET"})," platform opens up a ",(0,r.jsx)(n.strong,{children:"new market space"})," and a chance to significantly differentiate your products. DASSET is a cutting-edge software solution that transforms standard compute+storage hardware into an AI-powered, privacy-first data hub. By offering devices with DASSET pre-installed, OEMs can step out of the crowded commodity NAS market and ",(0,r.jsx)(n.strong,{children:"sail into a \u201cblue ocean\u201d of new demand"})," \u2013 providing customers an experience they can\u2019t get elsewhere. In short, DASSET lets you offer a ",(0,r.jsx)(n.strong,{children:"unique value proposition"})," (intelligent, user-controlled storage) under your own brand, giving you a compelling edge over competitors."]}),"\n",(0,r.jsxs)(n.p,{children:["Current NAS and cloud solutions in the market each have their limitations. None combine ",(0,r.jsx)(n.strong,{children:"on-device AI, robust privacy, and ease of use"})," in a single package the way DASSET does\u200b. This means there is a sizable segment of consumers and small businesses looking for smarter storage solutions that existing products aren\u2019t fully satisfying. By integrating DASSET into your hardware, you can ",(0,r.jsx)(n.strong,{children:"instantly position your devices in a class of their own"}),". Out of the box, a DASSET-powered device offers features like automatic photo organization, natural language search, and local AI analytics \u2013 capabilities that traditionally were only found (in limited form) in big cloud ecosystems, not in personal storage devices. Now users can have that intelligence and keep their data on-premises."]}),"\n",(0,r.jsxs)(n.p,{children:["For an OEM, this is a chance to ",(0,r.jsx)(n.strong,{children:"leapfrog competitors"})," without years of in-house software R&D. You focus on making great hardware, and PlanetX Labs provides the sophisticated software layer that today\u2019s users demand. The result is a ",(0,r.jsx)(n.strong,{children:"premium product"})," that commands differentiation \u2013 customers will see your device as not just another NAS, but as a \u201csmart personal cloud\u201d solution. In strategy terms, this is a blue ocean: instead of fighting on price or incremental features (where everyone else competes), you\u2019re creating a new category where you are the leader. Early adopters of DASSET in the OEM space can capture loyal customers who value privacy and control, gain press and industry attention for innovation, and set higher price points justified by the richer feature set."]}),"\n",(0,r.jsx)(n.h2,{id:"flexible-licensing-and-branding-options",children:"Flexible Licensing and Branding Options"}),"\n",(0,r.jsx)(n.p,{children:"PlanetX Labs offers licensing models tailored for OEM partners, ensuring you have flexibility in how you bring DASSET to market with your products. There are two primary tiers currently available\u200b:"}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"DASSET OEM Basic"})," \u2013 This includes the core DASSET functionality that we\u2019ve described (the essential NAS features and baseline AI capabilities) under ",(0,r.jsx)(n.strong,{children:"your branding"}),". You can ",(0,r.jsx)(n.strong,{children:"white-label"})," the software as your own NAS OS if desired, while still advertising the advanced features it provides. PlanetX Labs will assist with basic hardware optimization for your specific device (ensuring drivers and performance are tuned) and will supply co-branded marketing materials to help launch the product\u200b. This option is great for OEMs who want to enhance their devices\u2019 feature list quickly and prefer the product to appear under their own brand umbrella."]}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"DASSET OEM Premium"})," - This tier unlocks ",(0,r.jsx)(n.strong,{children:"the full feature set of DASSET"}),", including all advanced AI and any cloud-integration features available\u200b. OEMs at this level can still fully brand the software to their liking, but also have the option for ",(0,r.jsx)(n.strong,{children:"co-branding"})," with PlanetX (e.g. \u201cPowered by DASSET\u201d) if that adds value in marketing. Premium licensing comes with deeper collaboration: PlanetX Labs provides intensive hardware-specific optimizations, joint marketing campaigns, and technical integration support to tailor the software perfectly to your device\u200b. There\u2019s even the possibility to request custom features exclusive to your hardware \u2013 for instance, if your device has a unique sensor or accelerator, PlanetX can help integrate support for it. Premium partners effectively get a ",(0,r.jsx)(n.strong,{children:"bespoke solution"})," built on the DASSET platform, plus strong go-to-market backing from PlanetX."]}),"\n"]}),"\n"]}),"\n",(0,r.jsxs)(n.p,{children:["Both licensing models are designed to ensure the ",(0,r.jsx)(n.strong,{children:"OEM retains brand visibility and customer relationship"}),". Whether you choose a silent integration or a co-branded approach, you\u2019ll be able to present the solution as a unique offering of your product line. Some OEMs may opt to use their own UI skin or add complementary apps \u2013 DASSET is flexible enough to accommodate such customizations. The key is that, under the hood, the user gets the full power of DASSET, and you as the OEM get a proven software and networking backbone maintained by PlanetX."]}),"\n",(0,r.jsx)(n.h2,{id:"co-marketing-and-revenue-sharing-opportunities",children:"Co-Marketing and Revenue Sharing Opportunities"}),"\n",(0,r.jsxs)(n.p,{children:["PlanetX Labs is keen on partnering for mutual ",(0,r.jsx)(n.strong,{children:"success"}),". When you integrate DASSET, you're not left to do all the marketing education alone. OEM partners receive co-marketing ",(0,r.jsx)(n.strong,{children:"support"})," - this can range from being featured in PlanetX's marketing channels (press releases, website showcases, joint case studies) to having ready-made marketing collateral (videos, comparison charts, demo scripts) that you can use in your campaigns. Joint branding opportunities, like a \"Powered by ",(0,r.jsx)(n.strong,{children:"DASSET"}),'" badge on your product, can lend credibility and communicate advanced capabilities to customers. PlanetX can also assist in training your sales team on how to pitch the unique benefits of a DASSET-powered device, ensuring you can clearly articulate the value to distributors and end buyers.']}),"\n",(0,r.jsxs)(n.p,{children:["Another aspect is the potential for revenue ",(0,r.jsx)(n.strong,{children:"sharing"})," on software services. For example, DASSET includes an app marketplace and optional premium software features (such as subscription-based cloud backup or advanced AI packs). As an OEM, you can arrange to get a share of revenue when users of your devices purchase premium software or services through the DASSET ecosystem. This aligns incentives: both you and PlanetX benefit from a larger active user base that engages with the platform. It's a model similar to how smartphone manufacturers benefit from app store ecosystems. By participating, you're not just selling a one-time hardware box; you can tap into ongoing software revenue streams. PlanetX Labs is open to crafting these arrangements to ensure a win-win scenario."]}),"\n",(0,r.jsxs)(n.p,{children:["Finally, with a differentiated product, your market ",(0,r.jsx)(n.strong,{children:"positioning"})," improves. Media and reviewers are more likely to highlight a NAS device that boasts AI capabilities and privacy focus. This can amplify your marketing efforts through organic PR. We've seen that consumers are increasingly concerned about data privacy (91% of users prefer solutions where they physically control data) - by aligning with DASSET, you can confidently market privacy and control as a feature, backed by tangible tech that supports those claims."]}),"\n",(0,r.jsx)(n.h2,{id:"technical-integration-certification-and-support",children:"Technical Integration, Certification, and Support"}),"\n",(0,r.jsxs)(n.p,{children:["Adopting a new software platform may sound daunting, but PlanetX Labs has a comprehensive OEM integration ",(0,r.jsx)(n.strong,{children:"program"})," to ensure a smooth path from development to launch. Here's what OEMs can expect in terms of technical partnership:"]}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"Engineering Consultation and Early Access:"})," From day one, PlanetX engineers will work with your hardware team to optimize DASSET for your device. This includes guidance on hardware selection (CPU, memory, storage configuration) if you're in design phase, and performance tuning if you have existing hardware. OEM partners get early access to upcoming DASSET features and updates, so you can plan your product roadmap in sync and even influence features that are important to your customers."]}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:'Certification - "DASSET Inside" Badge:'}),' PlanetX offers a certification process to verify that your device runs DASSET optimally and securely. They will test your hardware against benchmarks for performance, stability, and security hardening. Devices that meet the criteria can carry the "DASSET ',(0,r.jsx)(n.strong,{children:'Inside"'})," badge or a similar certification mark. This not only assures customers of a quality experience, but also gives your product a marketing differentiator. Certification typically comes hand-in-hand with tuning recommendations - for example, if a certain storage controller needs a custom driver for best results, PlanetX will help develop and integrate that."]}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"Integration Tools and Documentation:"})," You'll receive detailed integration documentation specific to OEMs - covering how to flash or install DASSET on your devices in manufacturing, how to configure default settings or branding, and how to bundle license keys if needed. Tools for automation (imaging the software onto devices at scale) are provided. In addition, reference designs and sample configurations are available, since PlanetX has tested DASSET on various reference hardware. This can significantly cut down the time your engineers spend on software bring-up."]}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"Ongoing Updates and Long-Term Support:"})," One huge advantage of partnering on software is offloading maintenance. PlanetX Labs will handle regular software ",(0,r.jsx)(n.strong,{children:"updates"})," for DASSET, delivering new features, improvements, and security patches over the air to devices in the field. This keeps your product fresh and secure without your team having to develop those updates. Of course, all updates are tested for compatibility with certified hardware. If needed, you can get updates early in a staging environment to validate before wider rollout. PlanetX's commitment is that a device launched with DASSET will continue to get cutting-edge capabilities over its life, prolonging its relevance in the ",(0,r.jsx)(n.strong,{children:"market"}),"."]}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"Training and Support for OEMs:"})," Your support and ops teams will be backed by PlanetX\nexpertise. They provide training materials and ",(0,r.jsx)(n.strong,{children:"resources"})," for your customer support reps so they can handle end-user questions about the DASSET software. If deeper issues arise, PlanetX offers an OEM support channel where your engineers can directly reach out for help in troubleshooting software-related issues. Essentially, you gain a partner who is as invested in the success of the end-customer as you are. This can be critical when selling to business customers who might have advanced queries - you won't be on your own to answer them."]}),"\n"]}),"\n"]}),"\n",(0,r.jsx)(n.h2,{id:"partner-with-us",children:"Partner with Us"}),"\n",(0,r.jsxs)(n.p,{children:["PlanetX Labs encourages interested OEMs to ",(0,r.jsx)(n.a,{href:"https://www.planetxlabs.io/contact",children:"reach out"})," early for a dialogue. Typically, the process would involve evaluating your target hardware for compatibility, discussing which licensing tier fits your goals, and perhaps running a pilot (like a proof-of-concept installation on one of your devices). From there, a formal partnership agreement would cover licensing terms, support scope, and go-to-market plans including any co-marketing. The integration phase can be swift \u2013 thanks to existing tools and documentation, some OEM partners have gotten a prototype DASSET-powered device running in a matter of weeks. Certification ensures that by the time you\u2019re ready to ship, the solution is rock-solid."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"In summary"}),", partnering with PlanetX Labs offers OEMs a chance to ",(0,r.jsx)(n.strong,{children:"innovate faster, reduce development costs, and capture new market share"}),". You bring a high-quality hardware product, and DASSET injects it with a software intelligence layer that is increasingly in demand. Together, it results in a differentiated offering that addresses unmet needs in the market. From licensing flexibility and technical support to co-marketing and revenue sharing, PlanetX Labs provides a full-spectrum partnership to make sure adopting DASSET is a smooth and profitable journey for an OEM. By seizing this opportunity, you position your company not just as a device manufacturer, but ",(0,r.jsx)(n.strong,{children:"as a provider of cutting-edge solutions"})," in the era of data privacy and AI \u2013 truly a blue ocean strategy that can propel your business forward.,  for more information."]})]})}function u(e={}){const{wrapper:n}={...(0,i.R)(),...e.components};return n?(0,r.jsx)(n,{...e,children:(0,r.jsx)(d,{...e})}):d(e)}},8453:(e,n,t)=>{t.d(n,{R:()=>o,x:()=>s});var a=t(6540);const r={},i=a.createContext(r);function o(e){const n=a.useContext(i);return a.useMemo((function(){return"function"==typeof e?e(n):{...n,...e}}),[n,e])}function s(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:o(e.components),a.createElement(i.Provider,{value:n},e.children)}}}]);